import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Plane } from '../Entity/Plane';
import { BATTLE_EVENT } from '../BattleEvents';
import { EXP_REWARD, expForLevel } from '../Config/ExpConfig';

export class ExpSystem implements System {

    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(BATTLE_EVENT.ENEMY_KILLED, this._onEnemyKilled, this);
        world.bus.on(BATTLE_EVENT.BOSS_KILLED, this._onBossKilled, this);
    }

    onDestroy(world: World): void {
        world.bus.off(BATTLE_EVENT.ENEMY_KILLED, this._onEnemyKilled, this);
        world.bus.off(BATTLE_EVENT.BOSS_KILLED, this._onBossKilled, this);
        this._world = null!;
    }

    onTick(_world: World, _dt: number): void {
        // 事件驱动，不需要每帧
    }

    private _onEnemyKilled(): void {
        this._addExp(EXP_REWARD.enemy);
    }

    private _onBossKilled(): void {
        this._addExp(EXP_REWARD.boss);
    }

    private _addExp(amount: number): void {
        const player = this._findPlayer();
        if (!player) return;

        player.exp += amount;

        // while：Boss 400 经验可能连升多级，每级发一次 LEVEL_UP
        let levelsGained = 0;
        while (player.exp >= player.expToNext) {
            player.exp -= player.expToNext;
            player.level++;
            player.expToNext = expForLevel(player.level);
            levelsGained++;
        }

        if (levelsGained > 0) {
            console.log(`[ExpSystem] 升级到 Lv.${player.level}`);
            this._world.bus.emit(BATTLE_EVENT.LEVEL_UP, levelsGained);
        }

        // 数据事实：经验变了。给经验条 UI 用
        this._world.bus.emit(
            BATTLE_EVENT.EXP_CHANGED,
            player.exp,
            player.expToNext,
            player.level,
        );
    }

    private _findPlayer(): Plane | null {
        for (const p of this._world.query<Plane>('player')) return p;
        return null;
    }
}